      "subject": "elective",
      "material": "terms",
      "term": "CNN Architectures",
      "definition": "Convolutional Neural Network (CNN) – the general family of models used for images.\nPopular pre-built architectures:\nLeNet – one of the earliest CNNs.\nAlexNet – helped popularize deep learning in 2012.\nVGG – simple, deep, and widely used for learning.\nResNet – solved the problem of training very deep networks.\nMobileNet – lightweight, made for phones/small devices.\nEfficientNet – balances accuracy and speed efficiently.",
      "pdfWording": "Convolutional Neural Network (CNN) – the general family of models used for images.\nPopular pre-built architectures:\nLeNet – one of the earliest CNNs.\nAlexNet – helped popularize deep learning in 2012.\nVGG – simple, deep, and widely used for learning.\nResNet – solved the problem of training very deep networks.\nMobileNet – lightweight, made for phones/small devices.\nEfficientNet – balances accuracy and speed efficiently.",
      "contentKind": "slide-excerpt",
      "questionStyle": "identify",
      "questionExcerpt": "Convolutional Neural Network (CNN) – the general family of models used for images.\nPopular pre-built architectures:\nLeNet – one of the earliest CNNs.\nAlexNet – helped popularize deep learning in 2012.\nVGG – simple, deep, and widely used for learning.\nResNet – solved the problem of training very deep networks.\nMobileNet – lightweight, made for phones/small devices.\nEfficientNet – balances accuracy and speed efficiently.",
      "detail": "Vision Transformers (ViT) also appear on page 9 as a newer approach. They are not CNN architectures.",
