      "term": "Resizing",
      "definition": "Raw images will come in wildly different dimensions/aspect ratios, especially if sourced from multiple places (web scraping + manual capture + public datasets).\nMethods:\nSimple resize/stretch - fast, but distorts aspect ratio if the original isn't square.\nResize + crop - preserves aspect ratio by cutting off edges.\nResize + pad (\"letterboxing\") - preserves aspect ratio by adding blank/black borders instead of cropping content out.",
      "pdfWording": "Raw images will come in wildly different dimensions/aspect ratios, especially if sourced from multiple places (web scraping + manual capture + public datasets).\nMethods:\nSimple resize/stretch - fast, but distorts aspect ratio if the original isn't square.\nResize + crop - preserves aspect ratio by cutting off edges.\nResize + pad (\"letterboxing\") - preserves aspect ratio by adding blank/black borders instead of cropping content out.",
