      "term": "Color Space Conversion",
      "definition": "RGB → Grayscale: reduces 3 color channels to 1, cutting file size/computation — used when color isn't a meaningful signal for the task (e.g., document text recognition, X-ray analysis where color is nonexistent/irrelevant anyway).\nRGB → HSV: separates color (hue) from intensity/brightness (saturation/value) — sometimes used when you want the model to be more robust to lighting changes, since brightness and color become independent dimensions instead of tangled together.",
